# =========================================================
# FUNCIONES GENERALES
# =========================================================

def email_valido(email):
    return bool(
        re.fullmatch(
            r"[^@\s]+@[^@\s]+\.[^@\s]+",
            email.strip()
        )
    )


def escapar(valor):
    return html.escape(str(valor or ""))


def guardar_sesion(response, username):
    session = getattr(response, "session", None)

    if session is None:
        return False

    st.session_state["access_token"] = session.access_token
    st.session_state["refresh_token"] = session.refresh_token
    st.session_state["username"] = username

    user = getattr(response, "user", None)

    if user is None:
        user = getattr(session, "user", None)

    if user is not None:
        st.session_state["user_id"] = user.id

    return True


def guardar_datos_contacto(user_id, email_contacto, avisos_email):
    supabase.table("profiles").update({
        "email_contacto": email_contacto,
        "avisos_email": avisos_email,
    }).eq("id", user_id).execute()

    respuesta = (
        supabase.table("profiles")
        .select("email_contacto,avisos_email")
        .eq("id", user_id)
        .maybe_single()
        .execute()
    )
    perfil_guardado = respuesta.data if respuesta is not None else None
    return bool(
        perfil_guardado
        and perfil_guardado.get("email_contacto") == email_contacto
        and perfil_guardado.get("avisos_email") is avisos_email
    )


def cerrar_sesion():
    try:
        supabase.auth.sign_out()
    except Exception:
        pass

    for key in [
        "access_token",
        "refresh_token",
        "username",
        "user_id",
        "seccion_activa",
        "pegatina_compartida",
        "fb_cache_datos",
        "fb_seccion_anterior",
        "fb_opinion_abierta",
        "fb_pagina_rutas",
        "fb_pagina_negocios",
        "fb_revision_negocio",
        "fb_negocio_publicado",
        "fb_busqueda_anterior",
        "fb_aviso_email_oculto",
        "fb_aviso_email_guardado",
    ]:
        st.session_state.pop(key, None)


def preparar_pegatina(archivo):
    if archivo.size > 5 * 1024 * 1024:
        raise ValueError("La imagen supera el máximo de 5 MB.")

    with Image.open(archivo) as original:
        if original.format not in {"PNG", "JPEG", "WEBP"}:
            raise ValueError("Utiliza una imagen PNG, JPG o WebP.")
        if original.width * original.height > 20_000_000:
            raise ValueError("La imagen es demasiado grande. Reduce sus dimensiones e inténtalo de nuevo.")
        imagen = ImageOps.exif_transpose(original).convert("RGBA")
        imagen.thumbnail((600, 600), Image.Resampling.LANCZOS)
        # Cuadrar el lienzo sin cortar el logotipo ni perder la transparencia.
        lienzo = Image.new("RGBA", (600, 600))
        lienzo.paste(imagen, ((600 - imagen.width) // 2, (600 - imagen.height) // 2))
        salida = BytesIO()
        lienzo.save(salida, format="WEBP", quality=80)
    resultado = base64.b64encode(salida.getvalue()).decode("ascii")
    if len(resultado) > 400_000:
        raise ValueError("La imagen sigue siendo demasiado pesada. Prueba con una imagen más sencilla.")
    return resultado


def subir_archivo_storage(archivo, carpeta, prefijo):
    extension = archivo.name.rsplit(".", 1)[-1].lower()

    nombre_archivo = (
        f"{carpeta}/"
        f"{prefijo}_"
        f"{datetime.now(timezone.utc).strftime('%Y%m%d%H%M%S%f')}"
        f".{extension}"
    )

    supabase.storage.from_(BUCKET_FAMILYBIKE).upload(
        nombre_archivo,
        archivo.getvalue(),
        file_options={
            "content-type": archivo.type,
            "upsert": "false"
        }
    )

    resultado_url = (
        supabase.storage
        .from_(BUCKET_FAMILYBIKE)
        .get_public_url(nombre_archivo)
    )

    if isinstance(resultado_url, dict):
        url = (
            resultado_url.get("publicUrl")
            or resultado_url.get("publicURL")
        )
    else:
        url = str(resultado_url)

    if not url or not url.startswith("http"):
        raise ValueError(
            "Supabase no ha devuelto la dirección pública del archivo."
        )

    return url


# =========================================================
# PROPUESTAS DE RUTAS DE LA COMUNIDAD
# =========================================================

def enlace_google_maps_valido(url):
    """Acepta enlaces HTTPS oficiales de Google Maps, sin redirecciones externas."""
    from urllib.parse import urlparse
    try:
        parsed = urlparse(url.strip())
        host = (parsed.hostname or "").lower()
        return (
            parsed.scheme == "https"
            and not parsed.username
            and not parsed.password
            and host in {
                "www.google.com", "google.com", "maps.google.com",
                "maps.app.goo.gl", "goo.gl", "www.google.es", "google.es"
            }
            and bool(parsed.path and parsed.path != "/")
        )
    except (ValueError, AttributeError):
        return False


